UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Nettle</strong> (Urtica dioica/urens) is a <strong>power herb</strong> - deeply nutritive, <strong>hemostatic</strong>, <strong>diuretic</strong>, <strong>anti-inflammatory</strong>, and <strong>antihistamine</strong>; one of the essential herbs of the Middle Ages in western Europe; a power herb alongside <a href="?herb=11"><strong>Reishi Mushroom</strong></a>, <a href="?herb=85"><strong>Plantain</strong></a>, <a href="?herb=1252"><strong>Solomon's Seal</strong></a>, and <a href="?herb=2632"><strong>Lion's Mane Mushroom</strong></a>. 30% protein (complete protein - every amino acid present); rich in vitamins A, C, D, E, K, B1-B6/B9, Mg, Ca, Se, Zn, Fe, and source of Vitamin C; "for anyone who is depleted, stressed, or ill." For <strong>menorrhagia</strong>: hemostatic - reduces heavy menstrual flow, slows bleeding, provides nourishment (cold or standard infusion); uterine tonic with <a href="?herb=155"><strong>Raspberry</strong></a>. For <strong>PCOS/PMOS</strong>: reduces elevated testosterone; helps with anovulatory issues and hormone regulation (tea, vinegar, or food). Nutritional tea for <strong>fertility</strong>; for <strong>anemia</strong> in pregnancy and <strong>iron deficiency</strong> - contains enough Vitamin C to metabolize iron; in Iron Tonic Syrup (4 T dried); avoid tannins, alkaloids, and strong volatile oils when supplementing iron. Post-menopausal nourishing tea for anemia and mineral support with <a href="?herb=134"><strong>Lemon Balm</strong></a> and <a href="?herb=885"><strong>Alfalfa</strong></a>. <strong>Antihistamine</strong> for <strong>allergies</strong> and <strong>hay fever</strong> (fresh herb best); hollow hairs (trichomes) contain histamine, acetylcholine, and serotonin - "urtification" (intentional whacking with fresh plant) is a therapeutic technique for <strong>arthritis</strong>. <strong>Diuretic</strong> - removes excess water and sodium; diuretic for <strong>rheumatoid arthritis</strong> (drains synovial fluid); in Urinary System Support glycerite with <a href="?herb=22"><strong>Burdock</strong></a>, <a href="?herb=1648"><strong>Dandelion</strong></a> leaf, and <a href="?herb=55"><strong>Peppermint</strong></a>. Nettle seeds used for kidney support. Liver excess: mineral-rich herb to buffer blood; hepatics alongside <a href="?herb=17"><strong>Schizandra</strong></a>, <a href="?herb=206"><strong>Milk Thistle</strong></a>, <a href="?herb=42"><strong>Red Clover</strong></a>, <a href="?herb=28"><strong>Cleavers</strong></a>, <a href="?herb=37"><strong>Yellow Dock</strong></a>. Skin excess: nerve cooling, decrease liver excitability; for <strong>eczema</strong>. Rubefacient (external topical irritant) - stimulates blood flow, relieves pain, and improves circulation. For <strong>chemo</strong> support: cooling, nutritive, provides minerals in tea; blood support. Stroke recovery (hypertension, atrial fibrillation, stage 4 CKD): with <a href="?herb=2233"><strong>Hibiscus</strong></a>, <a href="?herb=28"><strong>Cleavers</strong></a>, <a href="?herb=2287"><strong>Oat Straw</strong></a> - herbs at midday, meds morning and evening. Regenerative tea blend: <a href="?herb=151"><strong>Horsetail</strong></a>, <a href="?herb=95"><strong>Corn Silk</strong></a>, Nettle, <a href="?herb=44"><strong>Yarrow</strong></a>, <a href="?herb=1014"><strong>Lady's Mantle</strong></a>, <a href="?herb=2233"><strong>Hibiscus</strong></a>, <a href="?herb=42"><strong>Red Clover</strong></a> (large daily infusions). Nutritive oxymel: Nettles, <a href="?herb=122"><strong>Dandelion</strong></a>, seaweed, <a href="?herb=2287"><strong>Oat Straw</strong></a>, <a href="?herb=885"><strong>Alfalfa</strong></a>. Dandelion/<a href="?herb=134"><strong>Lemon Balm</strong></a>/Nettle/<a href="?herb=124"><strong>Ginger</strong></a> tea for bloating and water retention. Fall self-care morning juicing blend with <a href="?herb=134"><strong>Lemon Balm</strong></a> and <a href="?herb=76"><strong>Fennel</strong></a>. Three parts Nettle in nourishing tea for bone density and nervous system support (long overnight infusion). Nettles and <a href="?herb=2287"><strong>Oat Straw</strong></a> in broth as a nourishing daily practice. Mineral-rich infusions for nervous system; oxymel formulation: 3 oz Nettle, 1 oz <a href="?herb=225"><strong>Astragalus</strong></a>. Good in salts and vinegars; nettle vinegar hair rinse conditioning. Preparation: GI nutritive - best extracted in water or vinegar over long periods; steep 1-4 hours; cold infusion for minerals (dark tea color = minerals present); spagyric process reincorporates minerals lost in alcohol extraction; vitamins only absorbed if eaten. <strong>Cooling and drying - NOT recommended for cold constitution; for dry constitution, use together with moistening herbs like <a href="?herb=134"><strong>Lemon Balm</strong></a>; caution for blood pressure patients.</strong>$$
WHERE id = 43;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Nettle Root</strong> (Urtica dioica) is an <strong>anti-inflammatory</strong> for <strong>men's health</strong>; specific for <strong>BPH</strong> (benign prostate inflammation), abnormal testosterone levels, and excess androgens - modulates androgens, promotes <strong>apoptosis</strong>, and down-regulates <strong>5-alpha reductase</strong> (super gentle); a hormone balancer for <strong>erectile dysfunction</strong>. Can use the <a href="?herb=43"><strong>Nettle</strong></a> leaf as a nutritive alongside it - seed too. BPH formula: <a href="?herb=186"><strong>Saw Palmetto</strong></a>, Nettle Root, <strong>Green Tea</strong>; alongside <a href="?herb=203"><strong>Turmeric</strong></a>, <a href="?herb=11"><strong>Reishi Mushroom</strong></a>, and <a href="?herb=14"><strong>Panax Ginseng</strong></a> to down-regulate 5-alpha reductase; Gaia Herbs formula suggested. Dose: 1-3 mL 3x/day; minimum 6 months for preventative use.$$
WHERE id = 1649;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Nigella</strong> (Black Seed; Nigella sativa) is an <strong>antibacterial</strong>, <strong>bronchodilator</strong>, <strong>carminative</strong>, <strong>diuretic</strong>, <strong>hepatoprotective</strong>, <strong>hypocholesterolemic</strong>, <strong>hypoglycemic</strong>, <strong>expectorant</strong>, and extremely <strong>gastroprotective</strong> herb used in the Unani-Tibb system. For <strong>metabolic syndrome</strong> (unhealthy blood lipids - use with <a href="?herb=203"><strong>Turmeric</strong></a>); for cold damp <strong>coughs</strong> and <strong>asthma</strong>. Dose: tincture 1:5 1-2 mL TID; capsules 500 mg BID; seed oil capsules 100-200 mg BID; consume as oil, tincture, or capsule. <strong>Contraindication: inhibits CYP2C11 pathway.</strong>$$
WHERE id = 2747;

