UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Nutmeg</strong> is a <strong>warming</strong> spice for cold constitution; richest spice in <strong>Vitamin A</strong>/Beta carotene. In Lisa's sleep formula: Nutmeg in milk with <a href="?herb=20"><strong>Ashwagandha</strong></a>; in <a href="?herb=20"><strong>Ashwagandha</strong></a>/<a href="?herb=167"><strong>Cinnamon</strong></a>/<a href="?herb=127"><strong>Cardamom</strong></a> milk formula for sleep.$$
