UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Oak</strong> bark is a <strong>constricting</strong> (tannin-rich) <strong>astringent</strong>; for <strong>hot damp diarrhea</strong>; astringent and <strong>antimicrobial</strong> for wound wash and infected wounds (applied externally as tincture or liniment).$$
WHERE id = 153;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Milky Oats</strong> is a <strong>trophorestorative</strong> and <strong>nervine</strong> - the "food for the nervous system"; specifically for "crispy fried nerve endings" - for people who have lost their buffer or cushion and perceive pain and sounds in amplified ways; for <strong>frayed nervous systems</strong>, long-term nervous exhaustion and depletion, emotional instability, drug withdrawal, mental scatter, <strong>ADHD</strong>, and anxiety-induced <strong>insomnia</strong>. Supports and repairs the <strong>myelin sheath</strong> - better for nerve degradation (e.g., MS) rather than initial nerve building; best used fresh after harvesting; for <strong>neuritis</strong> (peripheral nerve inflammation). <strong>Moistening</strong> - indicated for adrenal fatigue and anxiety; helps with muscle tension associated with loss of emolliency and not enough fats. Nervine for <strong>thyroid</strong> health (use based on whether patient needs scaffolding or calming); in adaptogen/nervine tincture for thyroid/<strong>Hashimoto's</strong> with <a href="?herb=20"><strong>Ashwagandha</strong></a> and <a href="?herb=78"><strong>Licorice</strong></a>. Nervine for <strong>rheumatoid arthritis</strong>; cools sympathetic stress response for musculoskeletal excess; neurorestorative for <strong>andropause</strong> alongside stress reduction, adaptogens, and circulatory stimulants. Oat straw/oat tops with asafetida: cardiovascular nervine support. Tonic tincture: Milky Oats, <a href="?herb=73"><strong>Hawthorn</strong></a> L+F, <a href="?herb=852"><strong>Shatavari</strong></a>, <a href="?herb=2229"><strong>Gotu Kola</strong></a>, <a href="?herb=2653"><strong>Bleeding Heart</strong></a>, <a href="?herb=25"><strong>Black Cohosh</strong></a>, <a href="?herb=90"><strong>Linden</strong></a> glycerite - would add <a href="?herb=2381"><strong>Bacopa</strong></a> and <strong>Mimosa</strong> for anti-inflammatory and heart/nerve nourishment. Sleep support during and after pregnancy (rotate remedies to avoid adaptation); insomnia in pregnancy. Preparation: milk is not soluble in water, only alcohol - does not work as tea; glycerine extracts both alcohol and water-soluble properties, making a more complex medicine; can be frozen.$$
WHERE id = 178;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Oat Straw</strong> is a <strong>nutritive</strong>, <strong>nervine tonic</strong>, and <strong>tissue restorative</strong> - high in silica (main medicine), calcium, and avenanthramides (antioxidants that aid circulation); "sets the stage for our emotional experience" - stabilizing and graceful, less volatile than other nervines. Supports <strong>nervous system</strong> vitality and calm focus; high in silica for <strong>hair, nails, and bones</strong> during puberty; mineral-rich nutritional tea for <strong>fertility</strong>. In stress-depletion mineral formula alongside <a href="?herb=155"><strong>Raspberry</strong></a> leaf, <a href="?herb=885"><strong>Alfalfa</strong></a>, <a href="?herb=42"><strong>Red Clover</strong></a>, and <a href="?herb=134"><strong>Lemon Balm</strong></a>. Hot-to-Cold Infusion for <strong>PTSD</strong> (incontinence, constipation, elevated cortisol): Oatstraw 3, <a href="?herb=13"><strong>Holy Basil</strong></a> 2, <a href="?herb=134"><strong>Lemon Balm</strong></a> 1. Stroke recovery (hypertension, atrial fibrillation, stage 4 CKD): with <a href="?herb=2233"><strong>Hibiscus</strong></a>, <a href="?herb=43"><strong>Nettle</strong></a>, <a href="?herb=28"><strong>Cleavers</strong></a> (herbs midday; meds morning and evening); caution for blood pressure. <a href="?herb=43"><strong>Nettle</strong></a> and Oat Straw in broth as a nourishing daily practice. Nutritive oxymel: <a href="?herb=43"><strong>Nettle</strong></a>, <a href="?herb=122"><strong>Dandelion</strong></a>, seaweed, Oat Straw, <a href="?herb=885"><strong>Alfalfa</strong></a>. Steady Study morning tea; three parts Oat Straw in nourishing tea for bone density and nervous system support (long overnight infusion). GI nutritive; oat straw/oat tops with asafetida as cardiovascular nervine support. Preparation: requires heat and long infusion to break cell walls; needs to be green and freshly dried; 4+ hours steep; cold infusion for mineral extraction.$$
WHERE id = 2287;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Ocotillo</strong> is a <strong>lymphagogue</strong> and <strong>circulatory stimulant</strong> - an energetic and physical mover of abdominal energies (administered as tincture). Specific lower body lymphatic affinity: for <strong>pelvic floor lymphatic congestion</strong>, lower abdomen and extremities; encourages <strong>venous return</strong> and poor leg circulation for sedentary individuals; lymph stimulant for cold constitution. Lymph/immune deficiency lymphagogue; immune stimulation for <strong>constipation</strong> with lymph congestion from buildup of waste in the large intestine. Lower GI deficiency (congestive type) to stimulate; <strong>female</strong> and <strong>male reproductive deficiency</strong> circulatory stimulant. For <strong>PMOS</strong>: improves circulation (lymphatic and blood), specific for <strong>liver inflammation</strong> and chronic poor <strong>fat digestion</strong>. Dose: tincture 10-30 drops 4x/day (smaller doses more frequently); commit 3-4 months to shift established body patterns.$$
WHERE id = 1248;
